.iwcp{--g:var(--e-global-color-primary);--y:var(--e-global-color-secondary);--sage:var(--e-global-color-accent);--ink:var(--e-global-color-text);--mist:var(--e-global-color-164e783);--white:var(--e-global-color-500cf27);
font-family:'Montserrat','Helvetica Neue',Helvetica,Arial,sans-serif;color:var(--ink);line-height:1.6;box-sizing:border-box}
.iwcp *,.iwcp *::before,.iwcp *::after{box-sizing:border-box}
.iwcp h1,.iwcp h2,.iwcp h3,.iwcp p{margin:0}
.iwcp a{color:inherit}
.iwcp img{max-width:100%}
.iwcp .wrap{max-width:1200px;margin:0 auto;padding:0 24px}
.iwcp .eyebrow{display:inline-block;font-size:12px;font-weight:700;letter-spacing:2px;text-transform:uppercase;color:var(--g)}
.iwcp .h2{font-size:clamp(28px,3.4vw,40px);line-height:1.2;font-weight:700;color:var(--g);letter-spacing:-.5px}
.iwcp .lead{font-size:18px;color:#3d4a42;max-width:650px}
.iwcp mark{background:linear-gradient(transparent 55%,var(--y) 55%);color:inherit;padding:0 4px}
.iwcp .btn{display:inline-flex;align-items:center;justify-content:center;min-height:52px;padding:16px 28px;border-radius:2px;background:var(--g);color:var(--white);font-weight:700;font-size:16px;text-decoration:none;transition:background .2s ease,color .2s ease}
.iwcp .btn:hover,.iwcp .btn:focus-visible{background:var(--y);color:var(--g)}
.iwcp .btn:focus-visible{outline:3px solid var(--g);outline-offset:3px}

/* top bar */
.iwcp.topbar{background:var(--g)}
.iwcp.topbar .wrap{display:flex;align-items:center;justify-content:space-between;gap:16px;min-height:72px}
.iwcp.topbar img{height:44px;width:auto;display:block}
.iwcp.topbar .call{font-size:15px;color:rgba(255,255,255,.85);text-decoration:none;white-space:nowrap}
.iwcp.topbar .call strong{color:var(--y)}
@media(max-width:600px){.iwcp.topbar .call span{display:none}.iwcp.topbar img{height:36px}}

/* hero copy (right column, above the form) */
.iwcp.hero-copy .chip{display:inline-flex;align-items:center;gap:8px;background:var(--g);color:var(--white);font-size:12px;font-weight:700;letter-spacing:1.6px;text-transform:uppercase;padding:8px 14px;border-radius:2px}
.iwcp.hero-copy .chip svg{flex:none}
.iwcp.hero-copy h1{font-size:clamp(34px,3.9vw,52px);line-height:1.1;font-weight:800;color:var(--g);letter-spacing:-1px;margin:18px 0 14px}
.iwcp.hero-copy .sub{font-size:17px;color:#34413a;max-width:540px}
.iwcp.hero-copy{margin-bottom:28px}
@media(max-width:767px){.iwcp.hero-copy h1{margin-top:16px}}

/* ticket over the hero photo */
.iwcp.ticket{display:flex;align-items:stretch;background:var(--white);border-radius:2px;box-shadow:0 14px 34px rgba(0,36,15,.28);max-width:340px;position:relative}
.iwcp.ticket .l{padding:16px 20px;border-right:2px dashed #cfd5c7;flex:1}
.iwcp.ticket .k{font-size:11px;font-weight:700;letter-spacing:1.8px;text-transform:uppercase;color:#5b6b43}
.iwcp.ticket .v{font-size:36px;font-weight:800;color:var(--g);line-height:1.05;letter-spacing:-1px}
.iwcp.ticket .r{padding:16px 18px;display:flex;flex-direction:column;justify-content:center;background:var(--y);color:var(--g);font-weight:800;font-size:13px;line-height:1.25;text-transform:uppercase;letter-spacing:1px;text-align:center;border-radius:0 2px 2px 0}
@media(max-width:767px){.iwcp.ticket{max-width:280px}.iwcp.ticket .v{font-size:28px}}

/* form card head + foot */
.iwcp.form-head{background:var(--g);color:var(--white);padding:16px 24px;border-radius:2px 2px 0 0}
.iwcp.form-head .t{font-size:18px;font-weight:700}
.iwcp.form-head .s{font-size:14px;opacity:.85;margin-top:2px}
.iwcp.form-foot{font-size:13px;color:#56615a;padding:0 24px 20px;display:flex;gap:8px;align-items:flex-start}
.iwcp.form-foot svg{flex:none;margin-top:3px}

/* trust strip */
.iwcp.trust{background:var(--g);color:var(--white)}
.iwcp.trust ul{list-style:none;margin:0 auto;padding:20px 24px;max-width:1200px;display:flex;flex-wrap:wrap;gap:12px 40px;justify-content:center}
.iwcp.trust li{display:flex;align-items:center;gap:10px;font-size:15px;font-weight:600}
.iwcp.trust svg{flex:none;color:var(--y)}
@media(max-width:600px){.iwcp.trust ul{flex-direction:column;align-items:flex-start;gap:12px;padding:24px}}

/* steps */
.iwcp.steps{padding:104px 0;background:var(--white)}
.iwcp.steps .grid{display:grid;grid-template-columns:repeat(4,1fr);gap:24px;margin-top:48px;counter-reset:s}
.iwcp.steps .step{position:relative;padding:28px 24px;background:var(--mist);border-radius:2px;border-top:4px solid var(--g)}
.iwcp.steps .num{width:44px;height:44px;border-radius:50%;background:var(--y);color:var(--g);font-weight:800;font-size:18px;display:flex;align-items:center;justify-content:center;margin-bottom:16px}
.iwcp.steps h3{font-size:18px;font-weight:700;color:var(--g);margin-bottom:6px}
.iwcp.steps p{font-size:15px;color:#3d4a42}
@media(max-width:1024px){.iwcp.steps .grid{grid-template-columns:repeat(2,1fr)}}
@media(max-width:600px){.iwcp.steps{padding:64px 0}.iwcp.steps .grid{grid-template-columns:1fr;gap:16px;margin-top:32px}}

/* prices */
.iwcp.prices{padding:104px 0;background:var(--mist)}
.iwcp.prices .grid{display:grid;grid-template-columns:repeat(3,1fr);gap:24px;margin-top:48px}
.iwcp.prices .card{background:var(--white);border-radius:2px;padding:28px 24px;display:flex;flex-direction:column;box-shadow:0 1px 2px rgba(0,48,23,.06);border:1px solid #e3e6dd}
.iwcp.prices .cat{font-size:11px;font-weight:700;letter-spacing:1.6px;text-transform:uppercase;color:#5b6b43}
.iwcp.prices h3{font-size:20px;font-weight:700;color:var(--g);margin:6px 0 2px}
.iwcp.prices .unit{font-size:14px;color:#5f6a63}
.iwcp.prices .price{display:flex;align-items:baseline;gap:12px;margin-top:20px;padding-top:16px;border-top:1px dashed #cfd5c7}
.iwcp.prices .was{font-size:16px;color:#6b746e;text-decoration:line-through}
.iwcp.prices .now{font-size:32px;font-weight:800;color:var(--g);letter-spacing:-.5px}
.iwcp.prices .tag{margin-left:auto;background:var(--y);color:var(--g);font-size:12px;font-weight:800;padding:4px 8px;border-radius:2px;white-space:nowrap}
.iwcp.prices .note{font-size:14px;color:#4d5a52;margin-top:32px;max-width:820px}
.iwcp.prices .more{margin-top:12px;font-size:15px;font-weight:700;color:var(--g)}
@media(max-width:1024px){.iwcp.prices .grid{grid-template-columns:repeat(2,1fr)}}
@media(max-width:600px){.iwcp.prices{padding:64px 0}.iwcp.prices .grid{grid-template-columns:1fr;gap:16px;margin-top:32px}}

/* lori */
.iwcp.lori{padding:104px 0;background:var(--white)}
.iwcp.lori .grid{display:grid;grid-template-columns:5fr 7fr;gap:64px;align-items:center}
.iwcp.lori .portrait{width:100%;height:auto;aspect-ratio:4/5;object-fit:cover;object-position:top;border-radius:2px;display:block}
.iwcp.lori p.body{font-size:17px;color:#34413a;margin:16px 0 24px;max-width:620px}
.iwcp.lori ul{list-style:none;padding:0;margin:0 0 32px;display:grid;gap:12px}
.iwcp.lori li{display:flex;gap:12px;align-items:flex-start;font-size:16px}
.iwcp.lori li svg{flex:none;margin-top:3px;color:var(--g)}
.iwcp.lori .photos{display:grid;grid-template-columns:1fr 1fr;gap:16px}
.iwcp.lori .photos img{width:100%;height:auto;aspect-ratio:4/3;object-fit:cover;border-radius:2px;display:block}
.iwcp.lori .cap{font-size:13px;color:#5f6a63;margin-top:8px}
@media(max-width:900px){.iwcp.lori{padding:64px 0}.iwcp.lori .grid{grid-template-columns:1fr;gap:32px}.iwcp.lori .portrait{max-width:420px;aspect-ratio:1/1}}

/* faq */
.iwcp.faq{padding:104px 0;background:var(--mist)}
.iwcp.faq .inner{max-width:820px;margin:0 auto;padding:0 24px}
.iwcp.faq details{background:var(--white);border:1px solid #e3e6dd;border-radius:2px;margin-top:12px}
.iwcp.faq details:first-of-type{margin-top:40px}
.iwcp.faq summary{list-style:none;cursor:pointer;padding:20px 56px 20px 24px;font-size:17px;font-weight:700;color:var(--g);position:relative}
.iwcp.faq summary::-webkit-details-marker{display:none}
.iwcp.faq summary::after{content:"+";position:absolute;right:24px;top:50%;transform:translateY(-50%);font-size:26px;font-weight:400;line-height:1}
.iwcp.faq details[open] summary::after{content:"\2212"}
.iwcp.faq summary:focus-visible{outline:3px solid var(--g);outline-offset:-3px}
.iwcp.faq .a{padding:0 24px 22px;font-size:16px;color:#34413a}
@media(max-width:600px){.iwcp.faq{padding:64px 0}}

/* cta copy (inside the cta container, which carries the photo) */
.iwcp.cta{max-width:560px}
.iwcp.cta .h2{color:var(--white)}
.iwcp.cta p{color:rgba(255,255,255,.9);font-size:18px;margin:16px 0 32px}
.iwcp.cta .row{display:flex;flex-wrap:wrap;gap:16px 24px;align-items:center}
.iwcp.cta .btn{background:var(--y);color:var(--g)}
.iwcp.cta .btn:hover,.iwcp.cta .btn:focus-visible{background:var(--white);color:var(--g)}
.iwcp.cta .call{color:var(--white);font-weight:600;text-decoration:underline;text-underline-offset:4px}

/* terms + footer */
.iwcp.foot{background:#00240f;color:rgba(255,255,255,.82);font-size:14px}
.iwcp.foot .terms{max-width:900px;margin:0 auto;padding:40px 24px 32px;border-bottom:1px solid rgba(255,255,255,.14)}
.iwcp.foot .terms strong{color:var(--white)}
.iwcp.foot .terms p{font-size:13px;line-height:1.6}
.iwcp.foot .bar{max-width:1200px;margin:0 auto;padding:28px 24px;display:flex;flex-wrap:wrap;gap:16px 32px;align-items:center;justify-content:space-between}
.iwcp.foot .bar a{color:var(--white)}
.iwcp.foot .bar .links{display:flex;gap:24px}

.iwcp .screen-reader-text{position:absolute!important;width:1px;height:1px;margin:-1px;padding:0;overflow:hidden;clip:rect(0,0,0,0);white-space:nowrap;border:0}
.iwcp.cta{position:relative}
