</div>
<script>
(function(){
var w=document.getElementById('book-online');
if(!w){return;}
var t=w.querySelectorAll('.bk-btn[data-cal]');
if(!t.length){return;}
var KEYS=['onsite','call'];
function load(n){
var p=document.getElementById('bk-'+n);
if(!p){return;}
var f=p.querySelector('iframe');
if(f&&!f.getAttribute('src')&&f.getAttribute('data-src')){f.setAttribute('src',f.getAttribute('data-src'));}
}
function warm(){KEYS.forEach(function(n){load(n);});}
function schedule(){
if(typeof window.requestIdleCallback==='function'){window.requestIdleCallback(warm,{timeout:3000});}
else{window.setTimeout(warm,1200);}
}
if(document.readyState==='complete'){schedule();}
else{window.addEventListener('load',schedule);}
function show(k){
KEYS.forEach(function(n){
var p=document.getElementById('bk-'+n);
if(!p){return;}
var on=(n===k);
p.hidden=!on;
if(on){load(n);}
});
Array.prototype.forEach.call(t,function(b){b.setAttribute('aria-expanded',b.getAttribute('data-cal')===k?'true':'false');});
try{window.dispatchEvent(new Event('resize'));}catch(err){}
}
Array.prototype.forEach.call(t,function(b){
var k=b.getAttribute('data-cal');
b.setAttribute('aria-controls','bk-'+k);
b.setAttribute('aria-expanded','false');
b.addEventListener('click',function(e){e.preventDefault();show(k);var p=document.getElementById('bk-'+k);if(p){p.scrollIntoView({behavior:'smooth',block:'start'});}});
});
})();
